/*
 * Custom Pinterest Background Style
 *
 * Instructions:
 * 1. Replace 'YOUR_IMAGE_URL_HERE' with the direct URL of your desired background image.
 * You'll need to upload your image to an image hosting service (e.g., Imgur, Postimage)
 * to get a direct link.
 * 2. The 'body' selector targets the entire page. If this doesn't work,
 * use the "Inspect" tool on Pinterest (Ctrl+Shift+I on Chromebook, then two-finger tap/Alt+click)
 * to find the main background element's ID or class, and replace 'body' with it
 * (e.g., '#main-content-wrapper' or '.pinterest-background-container').
 */
body {
  /* Set your background image URL here */
  background-image: url('https://i.postimg.cc/RJfYCDB9/%20%287%29.jpeg');

  /* Control how the image is sized */
  background-size: cover; /* Scales the image to cover the entire area, may crop */
  /* Alternative sizes:
     background-size: contain; /* Scales to fit, may leave empty space */
     background-size: 100% 100%; /* Stretches to fill, may distort */
 

  /* Prevent the image from repeating */
  background-repeat: no-repeat;

  /* Keep the background image fixed when you scroll */
  background-attachment: fixed;

  /* Center the background image */
  background-position: center center;

  /* Optional: Add a fallback background color in case the image doesn't load */
  background-color: #f0f0f0; /* A light grey fallback */
}
